import{_ as t,o,c as a,a3 as i}from"./chunks/framework.fntC-tS-.js";const f=JSON.parse('{"title":"Launching the geocomputing coffee","description":"","frontmatter":{"title":"Launching the geocomputing coffee","date":"2023-10-26T00:00:00.000Z","author":"Ludovic Räss","tags":["Geocomputing-coffee","Event","Git","Julia"]},"headers":[],"relativePath":"events/geocomp-coffee-1.md","filePath":"events/geocomp-coffee-1.md","lastUpdated":1794345340000}'),n={name:"events/geocomp-coffee-1.md"};function r(c,e,s,l,h,u){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="launching-the-geocomputing-coffee" tabindex="-1">Launching the geocomputing coffee <a class="header-anchor" href="#launching-the-geocomputing-coffee" aria-label="Permalink to &quot;Launching the geocomputing coffee&quot;">​</a></h1><h3 id="what-is-the-geocomputing-coffee-about" tabindex="-1">☕ What is the geocomputing coffee about? <a class="header-anchor" href="#what-is-the-geocomputing-coffee-about" aria-label="Permalink to &quot;:coffee: What is the geocomputing coffee about?&quot;">​</a></h3><p>The geocomputing coffee aims at an informal get-together with people interested in – or curious about – the geocomputing thematic. The idea is to provide a relaxed venue to exchange and learn about computational-related topics and share your latest advances or discuss technical issues.</p><blockquote><p>Find most of the material presented during the geocomputing coffee on GitHub <a href="https://github.com/Unil-SGC/geocomputing-coffee" target="_blank" rel="noreferrer">https://github.com/Unil-SGC/geocomputing-coffee</a>.</p></blockquote><h3 id="welcome" tabindex="-1">🎉 Welcome <a class="header-anchor" href="#welcome" aria-label="Permalink to &quot;:tada: Welcome&quot;">​</a></h3><p>As a <strong>first get-together</strong>, the goal of this meeting is to:</p><ul><li>(Re)-introduce briefly the Swiss Geocomputing Centre (SGC) <ul><li>Website <a href="https://unil-sgc.github.io" target="_blank" rel="noreferrer">https://unil-sgc.github.io</a></li><li>GitHub organisation <a href="https://github.com/Unil-SGC" target="_blank" rel="noreferrer">https://github.com/Unil-SGC</a></li><li>Discord chat server</li></ul></li><li>Introduce the activities we plan to offer within the SGC <strong>geocomputing coffee</strong></li><li>Provide a hands-on about version control and reproducible science using good-practices and tools for software carpentry.</li></ul><h3 id="hands-on" tabindex="-1">💻 Hands-on <a class="header-anchor" href="#hands-on" aria-label="Permalink to &quot;:computer: Hands-on&quot;">​</a></h3><p>During this first meeting, we will also cover the following technical topics:</p><ul><li>demo about the basics of using git, GitHub, and Julia</li><li>syncing local and remote repos using git</li><li>running interactively on <code>Curnagl</code> GPU node</li></ul><h3 id="what-s-next" tabindex="-1">What&#39;s next? <a class="header-anchor" href="#what-s-next" aria-label="Permalink to &quot;What&#39;s next?&quot;">​</a></h3><p>Stay tuned (joining the SGC Discord server) about future geocomputing coffee! We plan to gather bi-weekly most probably on Thursday, 10h30 - 11h30 or 12h15 - 13h15.</p>',12)])])}const p=t(n,[["render",r]]);export{f as __pageData,p as default};
